CREATE COLUMN TABLE "TEST_AP"."APZ_D_ELN1" ("ID" INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL , "EventCode" NVARCHAR(50), "Title" NVARCHAR(100), "Message" NVARCHAR(254), "Image" NVARCHAR(250), "Data" NVARCHAR(100), "DataExtra" NVARCHAR(5000), "SendUser" VARCHAR(4000), "SendAll" CHAR(1) CS_FIXEDSTRING DEFAULT 'N', "Pending" CHAR(1) CS_FIXEDSTRING DEFAULT 'Y', "Success" CHAR(1) CS_FIXEDSTRING DEFAULT 'N', "Retry" INTEGER CS_INT DEFAULT 0, "Method" NVARCHAR(50) DEFAULT 'app', "CreateDate" DATE CS_DAYDATE DEFAULT CURRENT_DATE, "UpdateDate" DATE CS_DAYDATE DEFAULT CURRENT_DATE, "Read" CHAR(1) CS_FIXEDSTRING DEFAULT 'N', "Note" NCLOB MEMORY THRESHOLD 1000, "DatabaseName" NVARCHAR(50), "IsRemove" CHAR(1) CS_FIXEDSTRING, PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE 